INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3363165, 465515, 24744, '<td valign="top">If you''re going for this kind of cliche, you should at least take a moment to line up the strings with the frame properly...</td>', 'If you''re going for this kind of cliche, you should at least take a moment to line up the strings with the frame properly...', '2007-02-14 00:12:35.000000', NULL, 1),
(3363183, 468432, 52713, '<td valign="top">nice textures, but this looks lke more than Basic editing</td>', 'nice textures, but this looks lke more than Basic editing', '2007-02-14 00:14:53.000000', NULL, 1),
(3363189, 465965, 15032, '<td valign="top">I like the contrast, but it looks a bit oversharpened from the lines on the sheet music</td>', 'I like the contrast, but it looks a bit oversharpened from the lines on the sheet music', '2007-02-14 00:16:01.000000', NULL, 1),
(3363193, 468287, 15032, '<td valign="top">Very nice!</td>', 'Very nice!', '2007-02-14 00:16:44.000000', NULL, 1),
(3363194, 468553, 62006, '<td valign="top">Nice DOF</td>', 'Nice DOF', '2007-02-14 00:16:45.000000', NULL, 1),
(3363195, 468485, 24744, '<td valign="top">I like the strong, simple composition and the string vibrating is a nice touch.  The lighting looks a little too tungsten biased to me, perhaps try adjusting the white balance?  It looks fine on the wood, but the strings look a bit yellow.</td>', 'I like the strong, simple composition and the string vibrating is a nice touch.  The lighting looks a little too tungsten biased to me, perhaps try adjusting the white balance?  It looks fine on the wood, but the strings look a bit yellow.', '2007-02-14 00:16:56.000000', NULL, 1),
(3363196, 468303, 15032, '<td valign="top">I like the perspective.  Unique for the challenge</td>', 'I like the perspective.  Unique for the challenge', '2007-02-14 00:16:57.000000', NULL, 1),
(3363201, 467912, 24744, '<td valign="top">Nice idea, but the lighting is a little flat for this subject.</td>', 'Nice idea, but the lighting is a little flat for this subject.', '2007-02-14 00:17:33.000000', NULL, 1),
(3363228, 468397, 24744, '<td valign="top">Nice idea and composition, perhaps the flower could be a little brighter</td>', 'Nice idea and composition, perhaps the flower could be a little brighter', '2007-02-14 00:21:02.000000', NULL, 1),
(3363238, 465319, 25884, '<td valign="top">nice, i just got a schecter myself... a 4 string stiletto elit-4.. they are great instruments, i upgraded from a MIM fender</td>', 'nice, i just got a schecter myself... a 4 string stiletto elit-4.. they are great instruments, i upgraded from a MIM fender', '2007-02-14 00:23:02.000000', NULL, 1),
(3363247, 468692, 56880, '<td valign="top">Nicely lit.  The color in the paper blends well with the instrument, giving the whole picture that "warm" look.  There were a lot of "instrument on sheets of music" shots, but I think this was the best.</td>', 'Nicely lit.  The color in the paper blends well with the instrument, giving the whole picture that "warm" look.  There were a lot of "instrument on sheets of music" shots, but I think this was the best.', '2007-02-14 00:25:16.000000', NULL, 1),
(3363253, 468630, 29011, '<td valign="top">Great idea with the setup. The whole color scheme and composition is very pleasing. I just find the image a bit flat lighting wise. This one definitly needs some contrast/levels adjustments.</td>', 'Great idea with the setup. The whole color scheme and composition is very pleasing. I just find the image a bit flat lighting wise. This one definitly needs some contrast/levels adjustments.', '2007-02-14 00:26:16.000000', NULL, 1),
(3363254, 465645, 56880, '<td valign="top">Nice perspective, but I think it would have helped the shot if the music in the background were a little more in focus, to at least make it easier to tell that it''s music.</td>', 'Nice perspective, but I think it would have helped the shot if the music in the background were a little more in focus, to at least make it easier to tell that it''s music.', '2007-02-14 00:26:22.000000', NULL, 1),
(3363263, 467209, 56880, '<td valign="top">Good choice of lighting; the shadows on the instrument give the image some depth.</td>', 'Good choice of lighting; the shadows on the instrument give the image some depth.', '2007-02-14 00:27:23.000000', NULL, 1),
(3363275, 467811, 24744, '<td valign="top">Nice use of shallow depth of field and good angle.  I find the dust on the black key is rather distracting though.</td>', 'Nice use of shallow depth of field and good angle.  I find the dust on the black key is rather distracting though.', '2007-02-14 00:29:39.000000', NULL, 1),
(3363277, 468205, 56880, '<td valign="top">Very nice setup with the reflection of the music in the instrument!</td>', 'Very nice setup with the reflection of the music in the instrument!', '2007-02-14 00:29:52.000000', NULL, 1),
(3363298, 468173, 24744, '<td valign="top">I like the natural border effect, very dramatic.</td>', 'I like the natural border effect, very dramatic.', '2007-02-14 00:34:18.000000', NULL, 1),
(3363306, 468692, 29011, '<td valign="top">Love the tones and softness here. An easy standout , and my first fave of the challenge.<br/>----<br/>Yep one of my favorites alright *bump*</td>', 'Love the tones and softness here. An easy standout , and my first fave of the challenge.----Yep one of my favorites alright *bump*', '2007-02-14 00:35:44.000000', NULL, 1),
(3363317, 468656, 24744, '<td valign="top">Very well composed, interesting take on a tired old cliche.</td>', 'Very well composed, interesting take on a tired old cliche.', '2007-02-14 00:38:25.000000', NULL, 1),
(3363318, 468206, 24744, '<td valign="top">Nice idea, the creases in the background are distracting though.</td>', 'Nice idea, the creases in the background are distracting though.', '2007-02-14 00:38:43.000000', NULL, 1),
(3363325, 468518, 24744, '<td valign="top">Going for the brown?</td>', 'Going for the brown?', '2007-02-14 00:39:18.000000', NULL, 1),
(3363327, 468645, 24744, '<td valign="top">Nice idea, and well composed and lit.</td>', 'Nice idea, and well composed and lit.', '2007-02-14 00:39:49.000000', NULL, 1),
(3363360, 468692, 24744, '<td valign="top">Strong composition and good lighting.</td>', 'Strong composition and good lighting.', '2007-02-14 00:45:13.000000', NULL, 1),
(3363382, 468630, 70375, '<td valign="top">For sure a pose ;) but perhaps just finished a practice? This is a tad on the dark side. I would like to see a little more of the beautiful grain on that wood :)</td>', 'For sure a pose ;) but perhaps just finished a practice? This is a tad on the dark side. I would like to see a little more of the beautiful grain on that wood :)', '2007-02-14 00:49:22.000000', NULL, 1),
(3363393, 467859, 70375, '<td valign="top">Nice composition! I love the B&amp;W too.... really makes the light work. The crop is just a tad too tight for my taste but it doesn''t distract a lot from the feel.</td>', 'Nice composition! I love the B&W too.... really makes the light work. The crop is just a tad too tight for my taste but it doesn''t distract a lot from the feel.', '2007-02-14 00:50:46.000000', NULL, 1),
(3363398, 468507, 70375, '<td valign="top">Love the B&amp;W :) This is a perfect example of music and school :)</td>', 'Love the B&W :) This is a perfect example of music and school :)', '2007-02-14 00:51:35.000000', NULL, 1),
(3363419, 465513, 70375, '<td valign="top">The wall in the bg is a tad of a distraction (there is a paint drop headed for the models nose)... but the silouhette is interesting... it kind of balances it out. I am not sure if you wanted the light or the dark... a true silouhette would have worked a bit better here I think... I could be wrong though... I oftentimes am :) Perhaps move a little away from the wall so it falls out of focus? Still, a great idea!</td>', 'The wall in the bg is a tad of a distraction (there is a paint drop headed for the models nose)... but the silouhette is interesting... it kind of balances it out. I am not sure if you wanted the light or the dark... a true silouhette would have worked a bit better here I think... I could be wrong though... I oftentimes am :) Perhaps move a little away from the wall so it falls out of focus? Still, a great idea!', '2007-02-14 00:55:26.000000', NULL, 1),
(3363424, 467935, 70375, '<td valign="top">I had a friend that played bass and he had a black fretless Fender... such memories. :)  I like the clarity and detail of this shot :)</td>', 'I had a friend that played bass and he had a black fretless Fender... such memories. :)  I like the clarity and detail of this shot :)', '2007-02-14 00:56:39.000000', NULL, 1),
(3363434, 465683, 70375, '<td valign="top">I played the flute too :) This is a lovely B&amp;W!! I like the shine on the instrument and the clarity of the notes on the paper :)</td>', 'I played the flute too :) This is a lovely B&W!! I like the shine on the instrument and the clarity of the notes on the paper :)', '2007-02-14 00:57:59.000000', NULL, 1),
(3363435, 465723, 72982, '<td valign="top">This one makes me smile.</td>', 'This one makes me smile.', '2007-02-14 00:58:01.000000', NULL, 1),
(3363437, 466542, 72982, '<td valign="top">I''d like this more if the notes were a sharper as opposed to her hands but otherwise I think it''s a great concept.</td>', 'I''d like this more if the notes were a sharper as opposed to her hands but otherwise I think it''s a great concept.', '2007-02-14 00:58:49.000000', NULL, 1),
(3363469, 468485, 15711, '<td valign="top">Cool. I love the vibration of the single string.  Nicely done.</td>', 'Cool. I love the vibration of the single string.  Nicely done.', '2007-02-14 01:04:07.000000', NULL, 1),
(3363473, 467150, 15711, '<td valign="top">I love the DOF.  This is darling. He looks like a young Prince Harry!!</td>', 'I love the DOF.  This is darling. He looks like a young Prince Harry!!', '2007-02-14 01:04:54.000000', NULL, 1),
(3363475, 467024, 15711, '<td valign="top">ROFL  This is a hoot.  I like the narrow DOF on the mouthpiece. What a darling image.</td>', 'ROFL  This is a hoot.  I like the narrow DOF on the mouthpiece. What a darling image.', '2007-02-14 01:05:38.000000', NULL, 1),
(3363489, 468486, 15711, '<td valign="top">HEE - I like that I can see the last part of Beethoven''s name.</td>', 'HEE - I like that I can see the last part of Beethoven''s name.', '2007-02-14 01:08:30.000000', NULL, 1),
(3363559, 468560, 66201, '<td valign="top">Great composition and it''s a nice clean shot. Well done.</td>', 'Great composition and it''s a nice clean shot. Well done.', '2007-02-14 01:21:15.000000', NULL, 1),
(3363561, 465468, 66201, '<td valign="top">"Violin" (sp)</td>', '"Violin" (sp)', '2007-02-14 01:21:44.000000', NULL, 1),
(3363583, 467265, 62006, '<td valign="top">Nice shot. Lighting looks good and B/W works for this composition. The foreground is a little distracting but overall good capture.</td>', 'Nice shot. Lighting looks good and B/W works for this composition. The foreground is a little distracting but overall good capture.', '2007-02-14 01:26:14.000000', NULL, 1),
(3363588, 468410, 72530, '<td valign="top">Very nice juxtaposition. Good luck!</td>', 'Very nice juxtaposition. Good luck!', '2007-02-14 01:26:50.000000', NULL, 1),
(3363599, 468205, 72530, '<td valign="top">This really stands out. The reflections are great. Good luck!</td>', 'This really stands out. The reflections are great. Good luck!', '2007-02-14 01:28:33.000000', NULL, 1),
(3363601, 468692, 72530, '<td valign="top">Nice rich lighting and good detail.</td>', 'Nice rich lighting and good detail.', '2007-02-14 01:28:44.000000', NULL, 1),
(3363613, 468599, 72530, '<td valign="top">GREAT angle. I''m looking forward to seeing the specs on this shot. I would''ve cleaned up some of the little white specs in the green, but otherwise it''s flawless to me. 10</td>', 'GREAT angle. I''m looking forward to seeing the specs on this shot. I would''ve cleaned up some of the little white specs in the green, but otherwise it''s flawless to me. 10', '2007-02-14 01:32:20.000000', NULL, 1),
(3363620, 468173, 66201, '<td valign="top">Very dramatic!</td>', 'Very dramatic!', '2007-02-14 01:34:06.000000', NULL, 1),
(3363632, 468405, 66201, '<td valign="top">Wow what a magnificent instrument!!! Want to swap? Mine''s old, and battered...Hope you''re still playing! Nice diagonals in this composition and I like the crop.</td>', 'Wow what a magnificent instrument!!! Want to swap? Mine''s old, and battered...Hope you''re still playing! Nice diagonals in this composition and I like the crop.', '2007-02-14 01:36:54.000000', NULL, 1),
(3363639, 466690, 66201, '<td valign="top">Very precious.I wish the poppet''s head had been in the light a fraction more, she disappears into the shadows.</td>', 'Very precious.I wish the poppet''s head had been in the light a fraction more, she disappears into the shadows.', '2007-02-14 01:37:43.000000', NULL, 1),
(3363645, 468476, 66201, '<td valign="top">What fantastic signage!! I just really don''t like what you''ve done with the processing in bringing out blue grain? Great subject though.</td>', 'What fantastic signage!! I just really don''t like what you''ve done with the processing in bringing out blue grain? Great subject though.', '2007-02-14 01:39:02.000000', NULL, 1),
(3363666, 468641, 66201, '<td valign="top">A fun set up that really works. I like the almost Desatyrated pallette and the overhead angle.</td>', 'A fun set up that really works. I like the almost Desatyrated pallette and the overhead angle.', '2007-02-14 01:51:20.000000', NULL, 1),
(3363669, 467150, 66201, '<td valign="top">Love this DOF and composition. Very nice work.</td>', 'Love this DOF and composition. Very nice work.', '2007-02-14 01:52:53.000000', NULL, 1),
(3363680, 468606, 66201, '<td valign="top">I love this subject and setup. Lovely take on the challenge topic. I also like the duotone and the whole "lost in another world" expression.</td>', 'I love this subject and setup. Lovely take on the challenge topic. I also like the duotone and the whole "lost in another world" expression.', '2007-02-14 01:55:46.000000', NULL, 1),
(3363689, 467204, 66201, '<td valign="top">What a sweet subject idea. There seems to be a bit of pixelation under the child''s index finger (over-sharpening?)....Also wondering if this wouldn''t have been more classical.nostalgic in B+W?</td>', 'What a sweet subject idea. There seems to be a bit of pixelation under the child''s index finger (over-sharpening?)....Also wondering if this wouldn''t have been more classical.nostalgic in B+W?', '2007-02-14 01:57:43.000000', NULL, 1),
(3363866, 468355, 69572, '<td valign="top">I wanted to do this one but didn''t have a guitar.  I love this pic</td>', 'I wanted to do this one but didn''t have a guitar.  I love this pic', '2007-02-14 03:30:36.000000', NULL, 1),
(3363868, 468661, 67671, '<td valign="top">Imo, the frame spoils it, looks a bit gimmicky, I like the composition, and the colors, focus is a little soft, but I think its intentional, if I ignore the frame, Id give it an 8, so lets ignore the frame, 8 it is.</td>', 'Imo, the frame spoils it, looks a bit gimmicky, I like the composition, and the colors, focus is a little soft, but I think its intentional, if I ignore the frame, Id give it an 8, so lets ignore the frame, 8 it is.', '2007-02-14 03:33:14.000000', NULL, 1),
(3363872, 465973, 67671, '<td valign="top">I''de love to hear whet she is playing, I like the shot, but I think the soft focus is a bit over done, 6</td>', 'I''de love to hear whet she is playing, I like the shot, but I think the soft focus is a bit over done, 6', '2007-02-14 03:36:47.000000', NULL, 1),
(3363946, 468552, 72817, '<td valign="top">love the moment!</td>', 'love the moment!', '2007-02-14 04:40:09.000000', NULL, 1),
(3363947, 468671, 72817, '<td valign="top">background is to noisy</td>', 'background is to noisy', '2007-02-14 04:40:33.000000', NULL, 1),
