(3364028, 467204, 20799, '<td valign="top">Wonderful</td>', 'Wonderful', '2007-02-14 05:27:11.000000', NULL, 1),
(3364046, 467451, 66201, '<td valign="top">Ah brilliant expression!!! I know that one well - I have a small boy violinist who gives me that one often. Excellent composition and title...works well.8</td>', 'Ah brilliant expression!!! I know that one well - I have a small boy violinist who gives me that one often. Excellent composition and title...works well.8', '2007-02-14 05:53:26.000000', NULL, 1),
(3364051, 465985, 66201, '<td valign="top">Lovely subject and great composition...I like the DOF and the fact that music is happening!</td>', 'Lovely subject and great composition...I like the DOF and the fact that music is happening!', '2007-02-14 05:55:14.000000', NULL, 1),
