(3365710, 468486, 29293, '<td valign="top">very cute</td>', 'very cute', '2007-02-14 13:48:18.000000', NULL, 1),
(3365714, 465645, 58610, '<td valign="top">Bravo! That''s for getting her to practice! She has perfect hand position on the bow, though her thumb could be bent just a little more and on the lower portion of the frog. Oh, the picture...right. Good detail and good lighting. Focusing on her hand is interesting in that it accentuates the action in this shot. Nice job.</td>', 'Bravo! That''s for getting her to practice! She has perfect hand position on the bow, though her thumb could be bent just a little more and on the lower portion of the frog. Oh, the picture...right. Good detail and good lighting. Focusing on her hand is interesting in that it accentuates the action in this shot. Nice job.', '2007-02-14 13:48:38.000000', NULL, 1),
(3365715, 466542, 29293, '<td valign="top">well a nude doesnt really imply school days but it is nice</td>', 'well a nude doesnt really imply school days but it is nice', '2007-02-14 13:48:55.000000', NULL, 1),
(3365720, 467227, 58610, '<td valign="top">Good comp and lighting.</td>', 'Good comp and lighting.', '2007-02-14 13:49:23.000000', NULL, 1),
(3365724, 466542, 70661, '<td valign="top">This is my favorite in this challenge. Great concept and very well carried out.</td>', 'This is my favorite in this challenge. Great concept and very well carried out.', '2007-02-14 13:49:53.000000', NULL, 1),
(3365726, 468605, 58610, '<td valign="top">Nice macro. Good job on the lighting and the comp/crop.</td>', 'Nice macro. Good job on the lighting and the comp/crop.', '2007-02-14 13:50:12.000000', NULL, 1),
(3365731, 468205, 70661, '<td valign="top">Excellent! One of my top picks.</td>', 'Excellent! One of my top picks.', '2007-02-14 13:50:37.000000', NULL, 1),
(3365733, 468173, 70661, '<td valign="top">Great idea, great shot &amp; I like how you did the border.</td>', 'Great idea, great shot & I like how you did the border.', '2007-02-14 13:51:15.000000', NULL, 1),
(3365734, 465239, 58610, '<td valign="top">This is a wonderful photo, but I don''t see the connection to "school days".</td>', 'This is a wonderful photo, but I don''t see the connection to "school days".', '2007-02-14 13:51:19.000000', NULL, 1),
(3365737, 468294, 67152, '<td valign="top">Very solid image - great focus on the face and eyes and wonderful perspective - ''staring down the barrel of the bell''.  The major thing I would have liked more is a little better lighting on his right eye - it is a little dark with an odd shadow making it look like a ''black eye''.</td>', 'Very solid image - great focus on the face and eyes and wonderful perspective - ''staring down the barrel of the bell''.  The major thing I would have liked more is a little better lighting on his right eye - it is a little dark with an odd shadow making it look like a ''black eye''.', '2007-02-14 13:52:16.000000', NULL, 1),
(3365739, 468485, 67152, '<td valign="top">Pizzicatto!  I really like the color and movement of the string being plucked.  Good lighting and composition as well. 8</td>', 'Pizzicatto!  I really like the color and movement of the string being plucked.  Good lighting and composition as well. 8', '2007-02-14 13:52:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3365741, 468685, 67152, '<td valign="top">nice lighting and placement of the trumpet player - well done</td>', 'nice lighting and placement of the trumpet player - well done', '2007-02-14 13:52:26.000000', NULL, 1),
(3365742, 467227, 67152, '<td valign="top">what a great face - love the ''I have THE look down'' expression - the lighting on the face is solid, but I would have liked just a little more lighting on the body of the guitar (tilt it up just a little)</td>', 'what a great face - love the ''I have THE look down'' expression - the lighting on the face is solid, but I would have liked just a little more lighting on the body of the guitar (tilt it up just a little)', '2007-02-14 13:52:29.000000', NULL, 1),
(3365743, 468432, 58610, '<td valign="top">Nice shot, but not "school days".</td>', 'Nice shot, but not "school days".', '2007-02-14 13:52:37.000000', NULL, 1),
(3365746, 467265, 67152, '<td valign="top">Very moody image.  The lighting on his shirt and face and the use of the hat and the stair railings to darken the image were all well done.</td>', 'Very moody image.  The lighting on his shirt and face and the use of the hat and the stair railings to darken the image were all well done.', '2007-02-14 13:53:10.000000', NULL, 1),
(3365755, 467859, 58610, '<td valign="top">Too bad you didn''t have a willing subject to play for your photo shoot. Meets the challenge, but is a rather boring subject and not well photographed.</td>', 'Too bad you didn''t have a willing subject to play for your photo shoot. Meets the challenge, but is a rather boring subject and not well photographed.', '2007-02-14 13:54:27.000000', NULL, 1),
(3365760, 467668, 34337, '<td valign="top">a bit grainy (note the cymbals on top).  Flash reflected in drums.</td>', 'a bit grainy (note the cymbals on top).  Flash reflected in drums.', '2007-02-14 13:55:44.000000', NULL, 1),
(3365763, 468626, 58610, '<td valign="top">Beautiful abstract. Really like the colors and the lighting.</td>', 'Beautiful abstract. Really like the colors and the lighting.', '2007-02-14 13:56:10.000000', NULL, 1),
(3365769, 467883, 34337, '<td valign="top">a bit too close.  good attempt at creativity.</td>', 'a bit too close.  good attempt at creativity.', '2007-02-14 13:56:59.000000', NULL, 1),
(3365780, 465248, 34337, '<td valign="top">great angle/persp.</td>', 'great angle/persp.', '2007-02-14 13:58:36.000000', NULL, 1),
(3365781, 468423, 58610, '<td valign="top">Verrry cute photo. I don''t get the makeup or how the title ties in.</td>', 'Verrry cute photo. I don''t get the makeup or how the title ties in.', '2007-02-14 13:58:38.000000', NULL, 1),
(3365788, 467497, 34337, '<td valign="top">could have used a bit more creativity (I''m working on this myself), but good focus and color.  Might have been a more striking photo without the pink and green music books.</td>', 'could have used a bit more creativity (I''m working on this myself), but good focus and color.  Might have been a more striking photo without the pink and green music books.', '2007-02-14 13:59:46.000000', NULL, 1),
(3365789, 466796, 67152, '<td valign="top">I like the background and use of natural light to bring out highlights in her hair in this image.  One thing seems strange to me however - it seems odd about the way she is holding the violin - it may be just the positioning in the photo...</td>', 'I like the background and use of natural light to bring out highlights in her hair in this image.  One thing seems strange to me however - it seems odd about the way she is holding the violin - it may be just the positioning in the photo...', '2007-02-14 13:59:47.000000', NULL, 1),
(3365800, 466886, 67152, '<td valign="top">Nice perspective - I like the Converse and the rolled up jeans (nice touch!).  The detail in the shoes and jeans are very well done</td>', 'Nice perspective - I like the Converse and the rolled up jeans (nice touch!).  The detail in the shoes and jeans are very well done', '2007-02-14 14:01:05.000000', NULL, 1),
(3365803, 465288, 34337, '<td valign="top">am I missing the music?</td>', 'am I missing the music?', '2007-02-14 14:01:25.000000', NULL, 1),
(3365806, 468432, 67152, '<td valign="top">Great composition and choice of sepia.  This image seems title dependent, but I will still give it a 7</td>', 'Great composition and choice of sepia.  This image seems title dependent, but I will still give it a 7', '2007-02-14 14:02:07.000000', NULL, 1),
(3365808, 468355, 67152, '<td valign="top">Very solid lighting and perspective on this image - the positioning of the neck across the image and the shallow DOF work well</td>', 'Very solid lighting and perspective on this image - the positioning of the neck across the image and the shallow DOF work well', '2007-02-14 14:02:13.000000', NULL, 1),
(3365809, 466033, 67152, '<td valign="top">Hilarious face! That is how I think i look when I try to play the trumpet (speaking as a trombone player).</td>', 'Hilarious face! That is how I think i look when I try to play the trumpet (speaking as a trombone player).', '2007-02-14 14:02:22.000000', NULL, 1),
(3365810, 466388, 34337, '<td valign="top">touch blurry.  do you have a tripod?  If so, use it often.</td>', 'touch blurry.  do you have a tripod?  If so, use it often.', '2007-02-14 14:02:23.000000', NULL, 1),
(3365811, 466835, 34337, '<td valign="top">great focus and clarity.</td>', 'great focus and clarity.', '2007-02-14 14:02:43.000000', NULL, 1),
(3365813, 468445, 34337, '<td valign="top">very well done</td>', 'very well done', '2007-02-14 14:02:57.000000', NULL, 1),
(3365816, 465550, 67152, '<td valign="top">Great perspective - love the colors and lighting from the stand lights.  Using shallow focus on the ''lead player'' is a nice touch.</td>', 'Great perspective - love the colors and lighting from the stand lights.  Using shallow focus on the ''lead player'' is a nice touch.', '2007-02-14 14:03:29.000000', NULL, 1),
(3365821, 468616, 34337, '<td valign="top">good creative angle.  some slight blurring.</td>', 'good creative angle.  some slight blurring.', '2007-02-14 14:04:12.000000', NULL, 1),
(3365827, 468303, 67152, '<td valign="top">Having the student looking up is a nice touch.  I doubt you would be able to make an electric piano look any more dramatic than you did.</td>', 'Having the student looking up is a nice touch.  I doubt you would be able to make an electric piano look any more dramatic than you did.', '2007-02-14 14:04:40.000000', NULL, 1),
(3365828, 467607, 34337, '<td valign="top">not with an Ibanez, she''s not  :)  Great pic.</td>', 'not with an Ibanez, she''s not  :)  Great pic.', '2007-02-14 14:04:42.000000', NULL, 1),
(3365829, 467132, 67152, '<td valign="top">very good image - excellent portrait and good capture to hit the music theme, but I really don''t see School Days - still, it gets a 7</td>', 'very good image - excellent portrait and good capture to hit the music theme, but I really don''t see School Days - still, it gets a 7', '2007-02-14 14:04:43.000000', NULL, 1),
(3365834, 468648, 34337, '<td valign="top">Edges seem pretty rough - not sure exactly why. But a good effort was made here.</td>', 'Edges seem pretty rough - not sure exactly why. But a good effort was made here.', '2007-02-14 14:05:53.000000', NULL, 1),
(3365843, 467811, 34337, '<td valign="top">Strange blurring/focus effects here.  Intriguing.</td>', 'Strange blurring/focus effects here.  Intriguing.', '2007-02-14 14:06:53.000000', NULL, 1),
(3365847, 466278, 67152, '<td valign="top">I really enjoy this one.  I think this is what every starting trombone feels like - the only one in the band, the one with the oom pah parts.  The use of duotone works well and the lighting to accentuate the trombone is a nice touch.</td>', 'I really enjoy this one.  I think this is what every starting trombone feels like - the only one in the band, the one with the oom pah parts.  The use of duotone works well and the lighting to accentuate the trombone is a nice touch.', '2007-02-14 14:07:03.000000', NULL, 1),
(3365852, 468461, 67152, '<td valign="top">The shallow DOF works very well.  I like the story that this image tells - distraction from practicing those silly G clefs... (I could never draw one very well...)</td>', 'The shallow DOF works very well.  I like the story that this image tells - distraction from practicing those silly G clefs... (I could never draw one very well...)', '2007-02-14 14:07:55.000000', NULL, 1),
(3365853, 468661, 34337, '<td valign="top">Could have done well without the inner border (gold).  The photo speaks for itslef.  Nice shot.</td>', 'Could have done well without the inner border (gold).  The photo speaks for itslef.  Nice shot.', '2007-02-14 14:08:02.000000', NULL, 1),
(3365857, 468692, 34337, '<td valign="top">Looks so real, I feel like I could touch it.  Very nice.</td>', 'Looks so real, I feel like I could touch it.  Very nice.', '2007-02-14 14:08:26.000000', NULL, 1),
(3365862, 468449, 67152, '<td valign="top">I like the perspective and the use of lighting, but there is a strange reddish tint to the image that is problematic to me - especially in her forehead and around her chin.  Taking the image all the way to B/W would likely have worked better.</td>', 'I like the perspective and the use of lighting, but there is a strange reddish tint to the image that is problematic to me - especially in her forehead and around her chin.  Taking the image all the way to B/W would likely have worked better.', '2007-02-14 14:09:16.000000', NULL, 1),
(3365863, 468612, 67152, '<td valign="top">Excellent image of a guitar - very crisp, great color, lovely composition. But, for this challenge I am personally looking for some connection to the learning or playing of the music (the whole School Days connection).  Still - you get a 7</td>', 'Excellent image of a guitar - very crisp, great color, lovely composition. But, for this challenge I am personally looking for some connection to the learning or playing of the music (the whole School Days connection).  Still - you get a 7', '2007-02-14 14:09:20.000000', NULL, 1),
(3365864, 467209, 67152, '<td valign="top">I like the written notation on the music - that is the touch that sets this type of image apart for me. 7</td>', 'I like the written notation on the music - that is the touch that sets this type of image apart for me. 7', '2007-02-14 14:09:24.000000', NULL, 1),
(3365865, 468648, 67152, '<td valign="top">I like the lighting a great deal, but I am not a huge fan of the cropping you chose.  The lead pipe seems cut off in a slightly awkward way. Still, it gets a 7..</td>', 'I like the lighting a great deal, but I am not a huge fan of the cropping you chose.  The lead pipe seems cut off in a slightly awkward way. Still, it gets a 7..', '2007-02-14 14:09:28.000000', NULL, 1),
(3365867, 466113, 34337, '<td valign="top">blurring/focus doesn''t seem natural, but this looks cool</td>', 'blurring/focus doesn''t seem natural, but this looks cool', '2007-02-14 14:09:59.000000', NULL, 1),
(3365873, 467658, 34337, '<td valign="top">small.  good contrast.</td>', 'small.  good contrast.', '2007-02-14 14:12:24.000000', NULL, 1),
(3365885, 466033, 69102, '<td valign="top">fun shot. wish the background wasn''t so drab.</td>', 'fun shot. wish the background wasn''t so drab.', '2007-02-14 14:14:29.000000', NULL, 1),
(3365888, 468641, 67152, '<td valign="top">I like the compsition of this image - the use of the music as the background is a good touch and the crumpled up music adds to the story.</td>', 'I like the compsition of this image - the use of the music as the background is a good touch and the crumpled up music adds to the story.', '2007-02-14 14:14:51.000000', NULL, 1),
(3365893, 468300, 69102, '<td valign="top">a little blown out. more contrast would have helped.</td>', 'a little blown out. more contrast would have helped.', '2007-02-14 14:16:13.000000', NULL, 1),
(3365901, 468618, 69102, '<td valign="top">this is well shot generally, but I had to look twice before I noticed the headphones as they get lost in the rest of the composition. also, not sure how listening to music on headphones alludes to freedom.</td>', 'this is well shot generally, but I had to look twice before I noticed the headphones as they get lost in the rest of the composition. also, not sure how listening to music on headphones alludes to freedom.', '2007-02-14 14:18:36.000000', NULL, 1),
(3365906, 468641, 73120, '<td valign="top">the frustration of the musician is so evident. Great Photo!</td>', 'the frustration of the musician is so evident. Great Photo!', '2007-02-14 14:19:18.000000', NULL, 1),
(3365910, 468297, 69102, '<td valign="top">like the exposure and the shallow dof, but the composition comes across flat to me.</td>', 'like the exposure and the shallow dof, but the composition comes across flat to me.', '2007-02-14 14:20:36.000000', NULL, 1),
(3365912, 465319, 69102, '<td valign="top">focus seems a little off.</td>', 'focus seems a little off.', '2007-02-14 14:20:57.000000', NULL, 1),
(3365917, 468692, 69102, '<td valign="top">very nice. like the soft, warm light.</td>', 'very nice. like the soft, warm light.', '2007-02-14 14:21:35.000000', NULL, 1),
(3365919, 467932, 69102, '<td valign="top">lighting needs work here.</td>', 'lighting needs work here.', '2007-02-14 14:21:56.000000', NULL, 1),
(3365923, 468553, 67152, '<td valign="top">This is a good solid image - use of music behind the recorder is a nice touch, lighting is solid, and shallow DOF is a good choice.  I would have preferred the music to actually of music for recorder, but that is my own little pet annoyance.</td>', 'This is a good solid image - use of music behind the recorder is a nice touch, lighting is solid, and shallow DOF is a good choice.  I would have preferred the music to actually of music for recorder, but that is my own little pet annoyance.', '2007-02-14 14:22:52.000000', NULL, 1),
(3365925, 468384, 69102, '<td valign="top">this looks a little overexposed, and the shadows in the background are distracting to the composition.</td>', 'this looks a little overexposed, and the shadows in the background are distracting to the composition.', '2007-02-14 14:22:59.000000', NULL, 1),
(3365928, 468287, 67152, '<td valign="top">A good solid image - the use of music is a good touch - especially since it is actually for clarinet.</td>', 'A good solid image - the use of music is a good touch - especially since it is actually for clarinet.', '2007-02-14 14:23:32.000000', NULL, 1),
(3365931, 466347, 69102, '<td valign="top">nice. i would have liked to either see more of the mic''s base or perhaps a slight crop to the right side.</td>', 'nice. i would have liked to either see more of the mic''s base or perhaps a slight crop to the right side.', '2007-02-14 14:23:58.000000', NULL, 1),
(3365934, 468673, 67152, '<td valign="top">This is a very interesting take on the Music challenge.  I like the random nature of this image (with the cases spread around).</td>', 'This is a very interesting take on the Music challenge.  I like the random nature of this image (with the cases spread around).', '2007-02-14 14:24:23.000000', NULL, 1),
(3365936, 467468, 69102, '<td valign="top">good mood on the lighting. highlights in the center are blown out, though.</td>', 'good mood on the lighting. highlights in the center are blown out, though.', '2007-02-14 14:24:41.000000', NULL, 1),
(3365943, 467668, 69102, '<td valign="top">lighting is too harsh at the bottom and too dark at the top. composition seems muddled and disorganized.</td>', 'lighting is too harsh at the bottom and too dark at the top. composition seems muddled and disorganized.', '2007-02-14 14:25:48.000000', NULL, 1),
(3365949, 466542, 67152, '<td valign="top">Very interesting approach at this challenge.  The lighting is solid and the use of the projector of music on her back is a good idea.</td>', 'Very interesting approach at this challenge.  The lighting is solid and the use of the projector of music on her back is a good idea.', '2007-02-14 14:27:34.000000', NULL, 1),
(3365951, 466388, 69102, '<td valign="top">a little too dark-recorder gets lost in the right side background. wish the focus was a little sharper, or at least more clearly located.</td>', 'a little too dark-recorder gets lost in the right side background. wish the focus was a little sharper, or at least more clearly located.', '2007-02-14 14:27:36.000000', NULL, 1),
(3365958, 468576, 67152, '<td valign="top">I think the perpective is very nice - with the randomness of the grass and the focus of the students face.  I think it could have been improved a little with a bit more contrast to bring out the player and the cello.</td>', 'I think the perpective is very nice - with the randomness of the grass and the focus of the students face.  I think it could have been improved a little with a bit more contrast to bring out the player and the cello.', '2007-02-14 14:29:00.000000', NULL, 1),
(3365960, 468618, 58610, '<td valign="top">Like the attitude! Nice comp and tonality. Very sharp.</td>', 'Like the attitude! Nice comp and tonality. Very sharp.', '2007-02-14 14:29:38.000000', NULL, 1),
(3365961, 468693, 67152, '<td valign="top">Nice closeup of the clarinet.  It is a solid image but other images in the challenge really told me more of a story than this one.</td>', 'Nice closeup of the clarinet.  It is a solid image but other images in the challenge really told me more of a story than this one.', '2007-02-14 14:29:46.000000', NULL, 1),
(3365964, 466325, 69102, '<td valign="top">seems like you are stretching for this one to fit the challenge. allegory is fine, but nothing about this shot says "music" except the title.</td>', 'seems like you are stretching for this one to fit the challenge. allegory is fine, but nothing about this shot says "music" except the title.', '2007-02-14 14:30:32.000000', NULL, 1),
(3365971, 467607, 69102, '<td valign="top">nice shot. wish there was a little more contrast between the subject and the background.</td>', 'nice shot. wish there was a little more contrast between the subject and the background.', '2007-02-14 14:31:30.000000', NULL, 1),
(3365973, 467468, 67152, '<td valign="top">The lighting seems a little odd to me.  It seems to work well for the instruments, but the background cloth and the piece of sheet music seem a little out of place and blown out.  Also, what bothers me is that the music is not for those instruments (it is piano music with guitar chord changes rather than brass music) and seems to be added as an afterthought.  The instruments alone would likely have worked better.</td>', 'The lighting seems a little odd to me.  It seems to work well for the instruments, but the background cloth and the piece of sheet music seem a little out of place and blown out.  Also, what bothers me is that the music is not for those instruments (it is piano music with guitar chord changes rather than brass music) and seems to be added as an afterthought.  The instruments alone would likely have worked better.', '2007-02-14 14:32:20.000000', NULL, 1),
(3365984, 468671, 58610, '<td valign="top">Excellent! Nice pov, good use of dof, well composed and lit.</td>', 'Excellent! Nice pov, good use of dof, well composed and lit.', '2007-02-14 14:34:21.000000', NULL, 1),
(3365985, 468423, 69102, '<td valign="top">the face paint actually makes her look like she has a black eye on first glance.</td>', 'the face paint actually makes her look like she has a black eye on first glance.', '2007-02-14 14:34:24.000000', NULL, 1),
(3365988, 468072, 67152, '<td valign="top">This is a solid image - good focus and lighting, nice background and good border.  It doesn''t jump off the screen at me, but it is well done. 7</td>', 'This is a solid image - good focus and lighting, nice background and good border.  It doesn''t jump off the screen at me, but it is well done. 7', '2007-02-14 14:35:07.000000', NULL, 1),
(3365989, 468410, 69102, '<td valign="top">too dark. composition needs work.</td>', 'too dark. composition needs work.', '2007-02-14 14:35:12.000000', NULL, 1),
(3365993, 465588, 67152, '<td valign="top">Thsi almost seems like too close for this kind of closeup.  It has some blown out sections on the keys on the top and there is a lot of the image that is OOF due to the shallow DOF.  You have some nice elements - music in the background, interesting lighting, good eye for composition, but it is hurt by the amount of soft focus areas.</td>', 'Thsi almost seems like too close for this kind of closeup.  It has some blown out sections on the keys on the top and there is a lot of the image that is OOF due to the shallow DOF.  You have some nice elements - music in the background, interesting lighting, good eye for composition, but it is hurt by the amount of soft focus areas.', '2007-02-14 14:37:15.000000', NULL, 1),
(3365996, 466358, 67152, '<td valign="top">What a great image.  Love the AC/DC sticker and the determined look on the face of the next "Keith Moon".  Bumping you to a 7</td>', 'What a great image.  Love the AC/DC sticker and the determined look on the face of the next "Keith Moon".  Bumping you to a 7', '2007-02-14 14:37:57.000000', NULL, 1),
(3366001, 468656, 67152, '<td valign="top">Nice clean composition and lighting.  This is well photographed and presented, but does not jump off the screen at me. 6</td>', 'Nice clean composition and lighting.  This is well photographed and presented, but does not jump off the screen at me. 6', '2007-02-14 14:38:58.000000', NULL, 1),
(3366007, 468354, 67152, '<td valign="top">Nice image - good perspective and reflections.  I think it would be more dramatic with a little more contrast - having the whites of the background music be a little whiter.</td>', 'Nice image - good perspective and reflections.  I think it would be more dramatic with a little more contrast - having the whites of the background music be a little whiter.', '2007-02-14 14:40:04.000000', NULL, 1),
