(3366187, 468296, 67152, '<td valign="top">Lovely perspective and composition.  I like the capture of the fingers mid motion.  7</td>', 'Lovely perspective and composition.  I like the capture of the fingers mid motion.  7', '2007-02-14 15:19:09.000000', NULL, 1),
(3366196, 468627, 67152, '<td valign="top">I like the theme of repeating lines (strings, grain of the wood).  I would have loved to see this in color and appreciate the natural wood tone.  The lighting does seem a little uneven, though, with the bottom of the body a little too dark compared to the neck.</td>', 'I like the theme of repeating lines (strings, grain of the wood).  I would have loved to see this in color and appreciate the natural wood tone.  The lighting does seem a little uneven, though, with the bottom of the body a little too dark compared to the neck.', '2007-02-14 15:20:56.000000', NULL, 1),
