(3368174, 466835, 63130, '<td valign="top">Very unique, I am bored by seeing so many similar images in this contest.</td>', 'Very unique, I am bored by seeing so many similar images in this contest.', '2007-02-15 00:55:37.000000', NULL, 1),
(3368177, 466542, 66201, '<td valign="top">Fantastic concept and composition. Back again: technically the only aspect that I might tweek is the DOF - the fact that such a small area of the photo is in focus (the 2 or so piano keys) is a bit of a problem. I might have tried to reverse the focus and get as much of the body focused as possible, sacrificing the piano in the process. Nevertheless, a really fantastic concept and I hope this does well.</td>', 'Fantastic concept and composition. Back again: technically the only aspect that I might tweek is the DOF - the fact that such a small area of the photo is in focus (the 2 or so piano keys) is a bit of a problem. I might have tried to reverse the focus and get as much of the body focused as possible, sacrificing the piano in the process. Nevertheless, a really fantastic concept and I hope this does well.', '2007-02-15 00:57:51.000000', NULL, 1),
(3368180, 466033, 66201, '<td valign="top">All round a great image: lovely clarity, and fun subject setup. I like the composition with face -on and centered subject. 9</td>', 'All round a great image: lovely clarity, and fun subject setup. I like the composition with face -on and centered subject. 9', '2007-02-15 01:00:20.000000', NULL, 1),
