(3374838, 465550, 73601, '<td valign="top">great colors</td>', 'great colors', '2007-02-17 10:16:25.000000', NULL, 1),
(3374843, 468202, 48471, '<td valign="top">Technically, many people here can tell better than me how to make a better shot. I''m here just to say that you get a couple of extra points for this being a photo shot in the street, with live and alive music...It''s refreshing after seeing so many dead instruments, to finally hear the music.</td>', 'Technically, many people here can tell better than me how to make a better shot. I''m here just to say that you get a couple of extra points for this being a photo shot in the street, with live and alive music...It''s refreshing after seeing so many dead instruments, to finally hear the music.', '2007-02-17 10:20:26.000000', NULL, 1);
