(3390525, 466542, 44534, '<td valign="top">Congratulations on first place..wonderful image, more ribbons to come!</td>', 'Congratulations on first place..wonderful image, more ribbons to come!', '2007-02-21 15:48:48.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3390530, 468692, 44534, '<td valign="top">Congratulations on your ribbon. A beautiful picture, I really like this one!</td>', 'Congratulations on your ribbon. A beautiful picture, I really like this one!', '2007-02-21 15:49:43.000000', NULL, 0),
(3390534, 467204, 44534, '<td valign="top">Congratulations, a wonderful shot!</td>', 'Congratulations, a wonderful shot!', '2007-02-21 15:50:41.000000', NULL, 0),
(3390539, 468576, 44534, '<td valign="top">Top five, way to go..Great picture!</td>', 'Top five, way to go..Great picture!', '2007-02-21 15:51:44.000000', NULL, 0),
(3390614, 468205, 32595, '<td valign="top">nice</td>', 'nice', '2007-02-21 16:24:48.000000', NULL, 0),
(3390652, 467204, 30982, '<td valign="top">Lovely, warm sentiment expressed here.  Well done.</td>', 'Lovely, warm sentiment expressed here.  Well done.', '2007-02-21 16:37:11.000000', NULL, 0),
(3390654, 465849, 30982, '<td valign="top">Congrats on the top 10!  This is a lovely picture and very much in the spirit of this challenge!</td>', 'Congrats on the top 10!  This is a lovely picture and very much in the spirit of this challenge!', '2007-02-21 16:38:04.000000', NULL, 0),
(3390666, 465988, 30982, '<td valign="top">I didn''t get a chance to vote in this challeng but I did wander through the images once, and this once caught my eye immediately.  This is very much in the spirit of the challenge and epitomizes the beauty of young people learning to appreciate music.  Very well composed (photographically - not sure of the composition they''re playing) and delightfully soft and gentle.  Very nice work.</td>', 'I didn''t get a chance to vote in this challeng but I did wander through the images once, and this once caught my eye immediately.  This is very much in the spirit of the challenge and epitomizes the beauty of young people learning to appreciate music.  Very well composed (photographically - not sure of the composition they''re playing) and delightfully soft and gentle.  Very nice work.', '2007-02-21 16:40:15.000000', NULL, 0),
(3390733, 465849, 19708, '<td valign="top">The only thing I would have changed on this, and now that I noticed it, can''t help but to be distracted by it,<br/>is the girl playing the flute - <i>(just kidding)</i> <br/> <br/>The little white triangle at the lower left is kind of distracting, and had this been mine, would have cloned it out.<br/> <br/>I still really like this.</td>', 'The only thing I would have changed on this, and now that I noticed it, can''t help but to be distracted by it,is the girl playing the flute - (just kidding)  The little white triangle at the lower left is kind of distracting, and had this been mine, would have cloned it out. I still really like this.', '2007-02-21 16:56:45.000000', NULL, 0),
(3390736, 468692, 58728, '<td valign="top">Lovely.  Congrats on your ribbon!!!<br/>It brings back memories for me...I played the clarinet when I was younger.  :)</td>', 'Lovely.  Congrats on your ribbon!!!It brings back memories for me...I played the clarinet when I was younger.  :)', '2007-02-21 16:58:40.000000', NULL, 0),
(3390954, 468621, 71931, '<td valign="top">I gave this a higher mark than I normally would due to the potential for this to be a very good shot with just a couple of small tweaks, especially cropping.  The problem with all impromptu shots is that they *are* in the spur of the moment, and thus don''t always fit into the nice, neat boxes of "form" and "composition" that we might prefer to see.  For me, as much as I enjoy all the benefits of digital photography, the one thing that I dislike so much about it is that it is <i>so</i> easy to correct minor flaws that we expect every shot to be perfect.  Sometimes a little imperfection makes for a better photograph, and I felt that this was one such case.  Crop it as a vertical image, which will eliminate 80% of the overlit background, and I think you''ve got a shot that you''ll be pleased to blow up to 8x10 and hang on a wall.</td>', 'I gave this a higher mark than I normally would due to the potential for this to be a very good shot with just a couple of small tweaks, especially cropping.  The problem with all impromptu shots is that they *are* in the spur of the moment, and thus don''t always fit into the nice, neat boxes of "form" and "composition" that we might prefer to see.  For me, as much as I enjoy all the benefits of digital photography, the one thing that I dislike so much about it is that it is so easy to correct minor flaws that we expect every shot to be perfect.  Sometimes a little imperfection makes for a better photograph, and I felt that this was one such case.  Crop it as a vertical image, which will eliminate 80% of the overlit background, and I think you''ve got a shot that you''ll be pleased to blow up to 8x10 and hang on a wall.', '2007-02-21 17:43:03.000000', NULL, 0),
(3390955, 468692, 64795, '<td valign="top">Lovely lighting and colors! Congrats on the ribbon!</td>', 'Lovely lighting and colors! Congrats on the ribbon!', '2007-02-21 17:43:13.000000', NULL, 0),
(3390966, 468692, 51538, '<td valign="top">Congratulations.  Nice photo and glad it was appreciated.</td>', 'Congratulations.  Nice photo and glad it was appreciated.', '2007-02-21 17:51:15.000000', NULL, 0),
(3391002, 465849, 38496, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Brad:</b></div><hr/><i> The only thing I would have changed on this, and now that I noticed it, can''t help but to be distracted by it,<br/>is the girl playing the flute - <i>(just kidding)</i> <br/> <br/>The little white triangle at the lower left is kind of distracting, and had this been mine, would have cloned it out.<br/> <br/>I still really like this. </i></td></tr></table> <br/> <br/>Yeah, it bugged me too, but it was basic, so what could I do.  I cropped as much out without losing any of the flute.<br/>Thanks for the comments!</td>', 'Originally posted by Brad: The only thing I would have changed on this, and now that I noticed it, can''t help but to be distracted by it,is the girl playing the flute - (just kidding)  The little white triangle at the lower left is kind of distracting, and had this been mine, would have cloned it out. I still really like this.   Yeah, it bugged me too, but it was basic, so what could I do.  I cropped as much out without losing any of the flute.Thanks for the comments!', '2007-02-21 18:00:15.000000', NULL, 0),
(3391226, 468173, 20168, '<td valign="top">Zoomy, Hey congrats on a great top 10 6th place finish! Now who is the composer? Time to head out of the Art Building and over the Music Building to learn to play this piece on the piano. I notice a few changes in time signature, always a fun little surprise for musicians! This just may be your highest Spokane photo to date! Lovely!</td>', 'Zoomy, Hey congrats on a great top 10 6th place finish! Now who is the composer? Time to head out of the Art Building and over the Music Building to learn to play this piece on the piano. I notice a few changes in time signature, always a fun little surprise for musicians! This just may be your highest Spokane photo to date! Lovely!', '2007-02-21 18:53:00.000000', NULL, 0),
(3391356, 468432, 70661, '<td valign="top">I like it...gave it a 8.</td>', 'I like it...gave it a 8.', '2007-02-21 19:30:56.000000', NULL, 0),
(3391429, 468432, 1031, '<td valign="top">For images like this I like the noisy, gritty look -- sometimes I just grab the Blue Channel alone and drop it into a new grayscale document. Your model definitely appears to have a passing familiarity with the Grouse ... : )</td>', 'For images like this I like the noisy, gritty look -- sometimes I just grab the Blue Channel alone and drop it into a new grayscale document. Your model definitely appears to have a passing familiarity with the Grouse ... : )', '2007-02-21 19:51:39.000000', NULL, 0),
(3391920, 466542, 9690, '<td valign="top">You missed an eighth note... no, wait, that''s a mole!</td>', 'You missed an eighth note... no, wait, that''s a mole!', '2007-02-21 22:29:42.000000', NULL, 0),
(3391963, 468432, 58728, '<td valign="top">I had given it a 10.  I really like this image.  The grain, and grunge feeling works for me.  Nicely done.</td>', 'I had given it a 10.  I really like this image.  The grain, and grunge feeling works for me.  Nicely done.', '2007-02-21 22:42:03.000000', NULL, 0),
(3392052, 465239, 50695, '<td valign="top">damn but you know how to take a picture.</td>', 'damn but you know how to take a picture.', '2007-02-21 23:06:35.000000', NULL, 0),
(3392550, 468537, 62318, '<td valign="top">Nice work Jeffrey. I like the "emotion" that everyone is talking about here. My only complaint is the serene emotion doesn''t seem to fit the stark background. Beyond that it is a great capture. I am a fan of side lighting so you get points from me.  I also like the grayscale treatment. I really do like the expression, it really makes the picture.</td>', 'Nice work Jeffrey. I like the "emotion" that everyone is talking about here. My only complaint is the serene emotion doesn''t seem to fit the stark background. Beyond that it is a great capture. I am a fan of side lighting so you get points from me.  I also like the grayscale treatment. I really do like the expression, it really makes the picture.', '2007-02-22 02:30:32.000000', NULL, 0),
(3392578, 468314, 62318, '<td valign="top">Great material. I like the use of toys because they are in general so colorful. You have everything placed nicely to convey a good use of the frame. The sharpness is also good. Just curious if you tried using any small model subjects? I think there is a certain life missing from the photo that would have helped with a little tyke. However, this is just a personal preference since I love shooting people :) It is a nice capture, colors pop and is a good product placement shot. I think as far as voting, I think the wrinkled curtain may have been the only thing that hurt. A terrific idea for the challenge.</td>', 'Great material. I like the use of toys because they are in general so colorful. You have everything placed nicely to convey a good use of the frame. The sharpness is also good. Just curious if you tried using any small model subjects? I think there is a certain life missing from the photo that would have helped with a little tyke. However, this is just a personal preference since I love shooting people :) It is a nice capture, colors pop and is a good product placement shot. I think as far as voting, I think the wrinkled curtain may have been the only thing that hurt. A terrific idea for the challenge.', '2007-02-22 02:53:03.000000', NULL, 0),
